// Every 10 minutes: tell Telegram when an audiobook request becomes available (or fails) in ReadMeABook.
const TOKEN = $env.HOMELAB_TELEGRAM_BOT_TOKEN, CHAT = String($env.HOMELAB_TELEGRAM_CHAT_ID || '');
const RMAB = 'http://192.168.3.201:3050', KEY = $env.HOMELAB_RMAB_TOKEN || '';
if (!KEY) throw new Error('Set RMAB_TOKEN in docker/n8n/.env (ReadMeABook → Settings → API)');
const s = $getWorkflowStaticData('global');
const get = (status) => this.helpers.httpRequest({ url: `${RMAB}/api/requests`, qs: { status, take: 50 }, headers: { Authorization: `Bearer ${KEY}` }, json: true, timeout: 20000 });
const [done, failed] = await Promise.all([get('completed'), get('failed')]);
const seen = new Set(s.seen || []);
const firstRun = !s.seen;
const msgs = [];
const label = (r) => `${r.audiobook?.title || 'Unknown title'}${r.audiobook?.author ? ` by ${r.audiobook.author}` : ''}`;
for (const r of done.requests || []) {
  const key = `ok:${r.id}`;
  if (!seen.has(key)) { seen.add(key); if (!firstRun) msgs.push(`🎧 Ready in Audiobookshelf: ${label(r)}`); }
}
for (const r of failed.requests || []) {
  const key = `fail:${r.id}`;
  if (!seen.has(key)) { seen.add(key); if (!firstRun) msgs.push(`⚠️ Couldn't get ${label(r)}. It will keep retrying daily; check ReadMeABook for details.`); }
}
s.seen = [...seen].slice(-500);
for (const text of msgs) await this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${TOKEN}/sendMessage`, body: { chat_id: CHAT, text }, json: true });
return msgs.length ? [{ json: { sent: msgs.length } }] : [];
